tests.command:
node --input-type=module - <<'EOF'
import { build } from 'vite';
const root = process.cwd() + '/experiments/planetary/astra-xhigh-minimal';
const result = await build({ root, configFile: false, logLevel: 'info', base: './', build: { write: false, minify: 'esbuild', rollupOptions: { input: root + '/index.html' } } });
const outputs = (Array.isArray(result) ? result : [result]).flatMap(result => result.output || []);
console.log('BUNDLE_CHECK_PASS', JSON.stringify(outputs.map(item => ({name:item.fileName, type:item.type, bytes:item.type === 'chunk' ? item.code.length : item.source.length}))));
EOF
